#!/usr/bin/env node
/* check-half-recipe — REFUSE a tree that changed source and shipped the base's generated bytes.
 * ═══════════════════════════════════════════════════════════════════════════════════════════════
 * WHY THIS EXISTS
 * On 2026-09-10 five branches, from three authors, arrived in this shape in one evening. Every
 * author was careful. IT IS A DETERMINISTIC PROPERTY OF THE PROCEDURE, NOT A SLIP:
 *
 *   a branch carrying a rebuild commit, rebased, with the generated files resolved CORRECTLY to
 *   the new base's side, EMPTIES that commit — and `git rebase` drops an empty commit by default.
 *
 * The result lints, typechecks, tests green and passes `check:asset-integrity`, because the map and
 * the files it maps are BOTH the base's. There is no conflict marker, no warning, no non-zero exit,
 * and `git log` shows nothing missing because the commit never existed on the new branch. An old
 * branch carries one rebuild per rebase it ever had: one branch lost THREE at once.
 *
 * CI's build-freshness step does catch it (`npm run build`, then `git diff --exit-code`), which is
 * why nothing has shipped. But that is a full gate cycle per occurrence. This is the same fact for
 * two `git` reads, available before the push.
 *
 * THE SIGNATURE IS THE CONJUNCTION, AND NEITHER HALF IS ON ITS OWN
 *   (1) the source delta touches something that compiles into a bundle
 *   (2) EVERY generated blob is identical to the base's
 * Condition 2 alone is an ordinary tooling-only branch — one landed the same night and MUST pass.
 * Condition 1 alone is an ordinary branch that did rebuild. Only together are they impossible: a
 * module cannot gain changed lines and leave its bundle byte-identical.
 *
 * THE GENERATED SET IS DERIVED, NEVER HAND-LISTED. It is read out of the BASE TREE itself, so
 * adding a bundle needs no edit here. A hand list goes stale the first time a bundle is added, and
 * a stale list is SILENTLY NARROWER — the failure direction that reads as a pass.
 *
 * THE FLOOR IS THE HALF THAT CAN GO QUIETLY WRONG. A glob that matches nothing makes condition 2
 * VACUOUSLY TRUE — all zero blobs are identical — and this would then approve every push while
 * printing something healthy. So the floor is a KNOWN COUNT (dist/ holds 10 files today), not a
 * token minimum: a floor of 3 is one a badly-broken glob can still clear.
 *
 * `*.test.*` is excluded from condition 1, so a branch that changes only tests — and legitimately
 * owes no rebuild — is not refused. That makes the check exact rather than merely conservative.
 *
 * THE ONE FALSE-REFUSAL SHAPE, STATED RATHER THAN HIDDEN. `src/data/bible-sync-*.js` and
 * `src/data/audio-sync.js` are fetched RAW and reach no bundle, so a branch touching only those
 * satisfies condition 1 without owing a rebuild. In practice it cannot trip this: any corpus-data
 * change also moves CORPUS_VERSION and the integrity hashes in service-worker.js, which breaks
 * condition 2. The REST of src/data (books.js, matthew-plain.js, bible-audio-manifest.js …) IS
 * bundled — build.py's PF1/PF2 member lists — so excluding src/data wholesale would be wrong.
 *
 * Run: node tools/check-half-recipe.mjs <base-ref> [head-ref]      (head defaults to HEAD)
 *
 * EXIT CODES — ONE MEANING EACH.
 *   0  clear — either the source delta is empty, or a generated file moved
 *   1  REFUSE — the half-recipe signature, with the source files named
 *   2  DEAD INSTRUMENT — the generated set or the source tree came back implausibly small. A check
 *      that found nothing must never report "clear": empty-equals-empty is how a broken extractor
 *      passes, and it passes while looking healthy.
 */
import { execFileSync } from 'node:child_process';

const A = 'app/src/main/assets';
const DIST_FLOOR = 8;      // dist/ holds 10 today; below 8 the glob is broken, not the tree
const SRC_FLOOR = 100;     // hundreds of .js/.jsx under src/; below this the ls-tree is broken
const ROOT_FLOOR = 3;      // app.css + the root .js files build.py folds (4 today); below 3 the derivation is broken

const git = (...args) => execFileSync('git', args, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
const lines = (s) => s.split('\n').map((l) => l.trim()).filter(Boolean);

const [, , baseArg, headArg = 'HEAD'] = process.argv;
if (!baseArg) {
  console.error('usage: node tools/check-half-recipe.mjs <base-ref> [head-ref]');
  process.exit(2);
}

let base;
let head;
try {
  base = git('rev-parse', '--verify', `${baseArg}^{commit}`).trim();
  head = git('rev-parse', '--verify', `${headArg}^{commit}`).trim();
} catch {
  console.error(`[half-recipe] DEAD INSTRUMENT — cannot resolve '${baseArg}' or '${headArg}'`);
  process.exit(2);
}

// ── the generated set, derived from the base tree ──────────────────────────────────────────────
const dist = lines(git('ls-tree', '--name-only', base, `${A}/dist/`));
if (dist.length < DIST_FLOOR) {
  console.error(`[half-recipe] DEAD INSTRUMENT — the dist/ glob returned ${dist.length} paths from ${baseArg} (floor ${DIST_FLOOR}).`);
  console.error("  REFUSING TO RUN rather than passing: with an empty set, 'every generated blob is");
  console.error("  identical' is true of nothing and this would clear every push.");
  process.exit(2);
}
const generated = [...dist, `${A}/service-worker.js`, `${A}/index.html`];

// ── condition 1: non-test source in the delta ──────────────────────────────────────────────────
// A GUARD'S SCOPE IS THE BUILD'S INPUT SET, NOT A DIRECTORY (2026-09-10, sw-chrome-fit). This
// used to read `${A}/src` alone, and app.css lives at the assets ROOT — build:css minifies it into
// dist/app.min.css and build.py folds it into bundle-a — so a stylesheet change with no build
// behind it read "no non-test source in the delta ... a tooling-only branch looks exactly like
// this and must pass". The half recipe, wearing the tooling-only label. The root inputs are
// DERIVED, never hand-listed: app.css (package.json's build:css input) plus every root .js file
// whose name build.py quotes, read from the base tree so a stale list cannot narrow silently.
const buildPy = git('show', `${base}:tools/build.py`);
const rootInputs = [`${A}/app.css`].concat(
  lines(git('ls-tree', '--name-only', base, `${A}/`))
    .filter((f) => /\.js$/.test(f) && !/\.test\.js$/.test(f) && !/service-worker\.js$/.test(f))
    .filter((f) => buildPy.includes(`'${f.slice(A.length + 1)}'`)),
);
if (rootInputs.length < ROOT_FLOOR) {
  console.error(`[half-recipe] DEAD INSTRUMENT — only ${rootInputs.length} root build inputs derived (floor ${ROOT_FLOOR}).`);
  console.error("  app.css plus the root .js files build.py names should be 4; a derivation reading fewer is");
  console.error('  broken, and a narrower input set is the failure direction that clears a half recipe.');
  process.exit(2);
}
const srcDelta = lines(git('diff', '--name-only', base, head, '--', `${A}/src`, ...rootInputs))
  .filter((f) => !/\.test\.[a-z]+$/.test(f));

// live control on the source extractor: the tree must contain source at all
const srcTree = lines(git('ls-tree', '-r', '--name-only', head, `${A}/src`)).filter((f) => /\.(js|jsx)$/.test(f));
if (srcTree.length < SRC_FLOOR) {
  console.error(`[half-recipe] DEAD INSTRUMENT — only ${srcTree.length} source files in ${headArg}'s tree (floor ${SRC_FLOOR}).`);
  process.exit(2);
}

// ── condition 2: every generated blob identical to the base's ──────────────────────────────────
const blob = (ref, path) => {
  try { return git('rev-parse', `${ref}:${path}`).trim(); } catch { return `absent-in-${ref.slice(0, 8)}`; }
};
const moved = generated.filter((g) => blob(base, g) !== blob(head, g));

const short = (r) => r.slice(0, 8);
console.log(`[half-recipe] base ${short(base)} → head ${short(head)}`);
console.log(`  generated paths derived from the base tree : ${generated.length}  (moved ${moved.length})`);
console.log(`  root build inputs derived from the base    : ${rootInputs.length}`);
console.log(`  non-test source files in the delta          : ${srcDelta.length}`);
if (moved.length) for (const m of moved) console.log(`    moved  ${m}`);

if (srcDelta.length > 0 && moved.length === 0) {
  console.error('');
  console.error(`  REFUSE — HALF RECIPE. ${srcDelta.length} source file(s) changed and NOT ONE of the`);
  console.error(`  ${generated.length} generated files moved. A module cannot gain changed lines and leave its`);
  console.error('  bundle byte-identical: the rebuild commit was emptied by the rebase and dropped.');
  console.error('  Run `npm run build` at the tip and commit it. The source with no build behind it:');
  for (const f of srcDelta) console.error(`    ${f}`);
  process.exit(1);
}

console.log(srcDelta.length === 0
  ? '  CLEAR — no non-test source in the delta, so no rebuild is owed (a tooling-only branch looks exactly like this and must pass).'
  : '  CLEAR — source changed AND generated output moved.');
